def word_histogram(string):
    string = string.lower()
    words = ''
    for char in string:
        if char.isalnum() or char.isspace():
            words += char
    words = words.split()
    histogram = {}
    for word in words:
        histogram[word] = histogram.get(word, 0) + 1
    return histogram

